const handleTabClick = (tabId: any) => {
    // Re-clicking the active tab must not re-filter or re-fetch.
    if (activeTab === tabId) {
        return;
    }
    // Remember filter/project for the tab we are leaving.
    lastFilterByTabRef.current[activeTab] = selectedFilter;
    lastProjectByTabRef.current[activeTab] = SelectedProject;

    // Reset shared search so returning to a tab starts with a clean query.
    setpendingSearch('');

    setVisitedTabs((prev) => {
        if (prev.has(tabId)) return prev;
        const next = new Set(prev);
        next.add(tabId);
        return next;
    });
    setActiveTab(tabId);
    setTimeout(() => recalcPaneHeights(), 100);

    if (tabId == 'hhhhootb-pane') {
        setOotbSearchMounted(true);
        setSelectedFilter('hhhhootb-pane');
        LocalselectedFilter = 'hhhhootb-pane';
        return;
    }
    if (tabId == 'pxc-pane') {
        // Spinner immediately so we never flash "No data available" before loadMasterTask runs.
        setIsFilterBusy(true);
        void loadMasterTask();
        return;
    }

    const defaults: Record<string, string> = {
        'suggestions-pane': 'suggestionPane',
        'status-pane': 'AllTask',
        'actions-pane': 'All',
        'weekbyme-pane': 'Created by me',
        'pasttasks-pane': 'Yesterday',
        'commentforme-pane': 'commentforme-pane',
        'routine-pane': 'routine-pane',
    };
    const restoreFilter =
        lastFilterByTabRef.current[tabId] != null && lastFilterByTabRef.current[tabId] !== ''
            ? lastFilterByTabRef.current[tabId]
            : (defaults[tabId] || 'AllTask');
    const restoreProject = lastProjectByTabRef.current[tabId];

    // Same filter already applied (e.g. shared MyBucket) — update selection only.
    if (restoreFilter === selectedFilter && restoreFilter === LocalselectedFilter) {
        return;
    }
    // Tab switches only re-filter cached AllData — never show the left-list skeleton.
    SelectedProject = restoreProject != null ? restoreProject : '';
    setSelectedFilter(restoreFilter);
    LocalselectedFilter = restoreFilter;
    lastFilterByTabRef.current[tabId] = restoreFilter;
    lastProjectByTabRef.current[tabId] = restoreProject;
    setSelectedTaskIds([]);
    getAllData(
        false,
        restoreFilter,
        SelectedDate ? SelectedDate : '',
        selectedActionFilter && restoreFilter != 'All' ? selectedActionFilter : '',
        true
    );
}
const handleFilterClick = (val: any, Project: any) => {
    SelectedProject = Project;
    setSelectedFilter(val);
    LocalselectedFilter = val;
    // Persist so re-opening this top-level tab restores the same sub-filter.
    if (activeTab) {
        lastFilterByTabRef.current[activeTab] = val;
